import React, { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "react-toastify";
import {
  FiCheck,
  FiEdit2,
  FiHeart,
  FiImage,
  FiPlus,
  FiRefreshCw,
  FiSave,
  FiSearch,
  FiTrash2,
  FiUploadCloud,
  FiX,
} from "react-icons/fi";

import api, { getApiErrorMessage } from "../../services/api";
import { useLanguage } from "../../contexts/LanguageContext";

const API_BASE_URL =
  process.env.REACT_APP_API_URL || "http://127.0.0.1:8000";

const INITIAL_CONTENT = {
  hero_title_en: "",
  hero_description_en: "",
  impact_title_en: "",
  impact_description_en: "",
  support_title_en: "",
  support_description_en: "",
  support_options_en: "",
  cta_title_en: "",
  cta_description_en: "",

  hero_title_km: "",
  hero_description_km: "",
  impact_title_km: "",
  impact_description_km: "",
  support_title_km: "",
  support_description_km: "",
  support_options_km: "",
  cta_title_km: "",
  cta_description_km: "",

  is_active: true,
};

const INITIAL_IMAGE_FORM = {
  title_en: "",
  title_km: "",
  description_en: "",
  description_km: "",
  image: "",
  order: 0,
  is_active: true,
};

const AdminCharity = () => {
  const { t, language } = useLanguage();
  const isKhmer = language === "km" || language === "kh";
  const suffix = isKhmer ? "km" : "en";

  const [content, setContent] = useState(INITIAL_CONTENT);
  const [images, setImages] = useState([]);
  const [imageForm, setImageForm] = useState(INITIAL_IMAGE_FORM);

  const [loadingContent, setLoadingContent] = useState(true);
  const [loadingImages, setLoadingImages] = useState(true);
  const [savingContent, setSavingContent] = useState(false);
  const [savingImage, setSavingImage] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);
  const [deletingId, setDeletingId] = useState(null);

  const [showImageForm, setShowImageForm] = useState(false);
  const [editingImageId, setEditingImageId] = useState(null);
  const [search, setSearch] = useState("");

  const tr = (key, english, khmer) => {
    const translated = typeof t === "function" ? t(key) : "";

    if (
      translated &&
      translated !== key &&
      !String(translated).includes("undefined")
    ) {
      return translated;
    }

    return isKhmer ? khmer : english;
  };

  const localized = (item, field, fallback = "") => {
    const selected = item?.[`${field}_${suffix}`];

    if (
      selected !== undefined &&
      selected !== null &&
      String(selected).trim() !== ""
    ) {
      return selected;
    }

    return fallback;
  };

  const getImageUrl = (path) => {
    if (!path) return "";

    const value = String(path);

    if (
      value.startsWith("http://") ||
      value.startsWith("https://") ||
      value.startsWith("blob:")
    ) {
      return value;
    }

    return value.startsWith("/")
      ? `${API_BASE_URL}${value}`
      : `${API_BASE_URL}/${value}`;
  };

  const apiError = (error, fallback) => {
    if (typeof getApiErrorMessage === "function") {
      return getApiErrorMessage(error, fallback);
    }

    const detail = error?.response?.data?.detail;

    if (typeof detail === "string") return detail;

    if (Array.isArray(detail)) {
      return detail
        .map((item) => item?.msg || item)
        .filter(Boolean)
        .join(", ");
    }

    return error?.response?.data?.message || error?.message || fallback;
  };

  const fetchContent = useCallback(async () => {
    try {
      setLoadingContent(true);

      const response = await api.get("/api/charity/");

      setContent({
        ...INITIAL_CONTENT,
        ...(response.data || {}),
      });
    } catch (error) {
      console.error("Fetch charity content error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.loadFailed",
            "Failed to load charity content.",
            "មិនអាចទាញយកមាតិកាសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setLoadingContent(false);
    }
  }, []);

  const fetchImages = useCallback(async () => {
    try {
      setLoadingImages(true);

      const response = await api.get("/api/charity/images/admin/all", {
        params: {
          skip: 0,
          limit: 200,
        },
      });

      const data = Array.isArray(response.data)
        ? response.data
        : Array.isArray(response.data?.items)
        ? response.data.items
        : [];

      setImages(data);
    } catch (error) {
      console.error("Fetch charity images error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.imagesLoadFailed",
            "Failed to load charity images.",
            "មិនអាចទាញយករូបភាពសប្បុរសធម៌បានទេ។"
          )
        )
      );

      setImages([]);
    } finally {
      setLoadingImages(false);
    }
  }, []);

  useEffect(() => {
    fetchContent();
    fetchImages();
  }, [fetchContent, fetchImages]);

  const filteredImages = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    if (!keyword) return images;

    return images.filter((item) =>
      [
        item.title_en,
        item.title_km,
        item.description_en,
        item.description_km,
        item.order,
      ]
        .filter((value) => value !== null && value !== undefined)
        .join(" ")
        .toLowerCase()
        .includes(keyword)
    );
  }, [images, search]);

  const handleContentChange = (field, value) => {
    setContent((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const handleImageFormChange = (event) => {
    const { name, value, type, checked } = event.target;

    setImageForm((current) => ({
      ...current,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const saveContent = async (event) => {
    event.preventDefault();

    try {
      setSavingContent(true);

      const payload = {
        ...content,
        is_active: Boolean(content.is_active),
      };

      delete payload.id;
      delete payload.updated_at;

      const response = await api.put("/api/charity/", payload);

      setContent({
        ...INITIAL_CONTENT,
        ...(response.data || {}),
      });

      toast.success(
        tr(
          "charity.savedSuccess",
          "Charity content saved successfully.",
          "បានរក្សាទុកមាតិកាសប្បុរសធម៌ដោយជោគជ័យ។"
        )
      );
    } catch (error) {
      console.error("Save charity content error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.saveFailed",
            "Failed to save charity content.",
            "មិនអាចរក្សាទុកមាតិកាសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setSavingContent(false);
    }
  };

  const resetImageForm = () => {
    setImageForm(INITIAL_IMAGE_FORM);
    setEditingImageId(null);
    setShowImageForm(false);
  };

  const openCreateImage = () => {
    setImageForm(INITIAL_IMAGE_FORM);
    setEditingImageId(null);
    setShowImageForm(true);
  };

  const openEditImage = (item) => {
    setImageForm({
      title_en: item.title_en || "",
      title_km: item.title_km || "",
      description_en: item.description_en || "",
      description_km: item.description_km || "",
      image: item.image || "",
      order:
        item.order !== undefined && item.order !== null
          ? Number(item.order)
          : 0,
      is_active:
        item.is_active === undefined ? true : Boolean(item.is_active),
    });

    setEditingImageId(item.id);
    setShowImageForm(true);

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  };

  const uploadImageFile = async (event) => {
    const file = event.target.files?.[0];

    if (!file) return;

    const allowedTypes = ["image/jpeg", "image/png", "image/webp"];

    if (!allowedTypes.includes(file.type)) {
      toast.error(
        tr(
          "charity.invalidImage",
          "Only JPG, PNG and WEBP images are allowed.",
          "អនុញ្ញាតតែរូបភាព JPG, PNG និង WEBP ប៉ុណ្ណោះ។"
        )
      );
      event.target.value = "";
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error(
        tr(
          "charity.imageTooLarge",
          "Image size must not exceed 5 MB.",
          "ទំហំរូបភាពមិនត្រូវលើសពី 5MB។"
        )
      );
      event.target.value = "";
      return;
    }

    const formData = new FormData();
    formData.append("file", file);

    try {
      setUploadingImage(true);

      const response = await api.post(
        "/api/charity/images/upload",
        formData
      );

      const imagePath = response.data?.path || response.data?.url;

      if (!imagePath) {
        throw new Error("Backend did not return image path.");
      }

      setImageForm((current) => ({
        ...current,
        image: imagePath,
      }));

      toast.success(
        tr(
          "charity.imageUploaded",
          "Image uploaded successfully.",
          "បាន Upload រូបភាពដោយជោគជ័យ។"
        )
      );
    } catch (error) {
      console.error("Upload charity image error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.uploadFailed",
            "Failed to upload image.",
            "មិនអាច Upload រូបភាពបានទេ។"
          )
        )
      );
    } finally {
      setUploadingImage(false);
      event.target.value = "";
    }
  };

  const saveImage = async (event) => {
    event.preventDefault();

    if (!imageForm.image) {
      toast.error(
        tr(
          "charity.imageRequired",
          "Please upload an image.",
          "សូម Upload រូបភាព។"
        )
