          )
        );
      } else {
        await api.post("/api/charity/images", payload);

        toast.success(
          tr(
            "charity.imageCreated",
            "Charity image added successfully.",
            "បានបន្ថែមរូបភាពសប្បុរសធម៌ដោយជោគជ័យ។"
          )
        );
