      resetImageForm();
      await fetchImages();
    } catch (error) {
      console.error("Save charity image error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.imageSaveFailed",
            "Failed to save charity image.",
            "មិនអាចរក្សាទុករូបភាពសប្បុរសធម៌បានទេ។"
