                `impact_description_${suffix}`,
                isKhmer
                  ? "ពិពណ៌នាអំពីផលប៉ះពាល់..."
                  : "Describe the impact...",
                true
              )}

              {renderContentInput(
                isKhmer ? "ចំណងជើងការគាំទ្រ" : "Support Title",
                `support_title_${suffix}`,
                isKhmer
                  ? "ការចូលរួមគ្រប់បែបយ៉ាងអាចបើកទ្វារឱកាស"
                  : "Every Contribution Can Open a Door"
              )}

              {renderContentInput(
                isKhmer ? "ចំណងជើង CTA" : "CTA Title",
                `cta_title_${suffix}`,
                isKhmer
                  ? "គាំទ្រសកម្មភាពសប្បុរសធម៌របស់ SC Academy"
                  : "Support SC Academy Charity"
              )}

              {renderContentInput(
                isKhmer
                  ? "ការពិពណ៌នាការគាំទ្រ"
                  : "Support Description",
                `support_description_${suffix}`,
                isKhmer
                  ? "ពិពណ៌នាពីរបៀបដែលមនុស្សអាចជួយ..."
                  : "Describe how people can help...",
                true
              )}

              {renderContentInput(
                isKhmer ? "ការពិពណ៌នា CTA" : "CTA Description",
                `cta_description_${suffix}`,
                isKhmer
                  ? "ទាក់ទងក្រុមការងារដើម្បីស្វែងយល់បន្ថែម..."
                  : "Contact us to learn more...",
                true
              )}

              <div className="md:col-span-2">
                {renderContentInput(
                  isKhmer ? "ជម្រើសការគាំទ្រ" : "Support Options",
                  `support_options_${suffix}`,
                  isKhmer
                    ? "មួយជម្រើសក្នុងមួយបន្ទាត់"
                    : "One option per line",
                  true
                )}
              </div>
            </div>

            <div className="flex justify-end border-t border-slate-200 px-5 py-4">
              <button
                type="submit"
                disabled={savingContent}
                className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-blue-900 px-6 text-[12px] font-bold text-white transition hover:bg-red-600 disabled:opacity-60"
              >
                {savingContent ? (
                  <>
                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
                    {tr(
                      "common.saving",
                      "Saving...",
                      "កំពុងរក្សាទុក..."
                    )}
                  </>
                ) : (
                  <>
                    <FiSave size={16} />
                    {tr(
                      "common.save",
                      "Save Content",
                      "រក្សាទុកមាតិកា"
                    )}
                  </>
                )}
              </button>
            </div>
          </form>
        </section>

        <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="flex flex-col gap-4 border-b border-slate-200 px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-[0.15em] text-red-600">
                {tr(
                  "charity.imageLibrary",
                  "Charity Image Library",
                  "បណ្ណាល័យរូបភាពសប្បុរសធម៌"
                )}
              </p>

              <h2 className="mt-1 text-[18px] font-bold text-blue-950">
                {tr(
                  "charity.images",
                  "Charity Images",
                  "រូបភាពសប្បុរសធម៌"
                )}
              </h2>
            </div>

            <div className="relative w-full sm:w-[300px]">
              <FiSearch
                size={15}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
              />
              <input
                type="search"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder={tr(
                  "charity.searchImages",
                  "Search images...",
                  "ស្វែងរករូបភាព..."
                )}
                className="h-10 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-[12px] outline-none focus:border-blue-800 focus:bg-white"
              />
            </div>
          </div>

          {loadingImages ? (
            <div className="flex min-h-[240px] items-center justify-center">
              <div className="h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-blue-900" />
            </div>
          ) : filteredImages.length === 0 ? (
            <div className="flex min-h-[260px] flex-col items-center justify-center px-5 text-center">
              <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-50 text-blue-900">
                <FiImage size={26} />
              </div>

              <h3 className="mt-4 text-[17px] font-bold text-blue-950">
                {tr(
                  "charity.noImages",
                  "No Charity Images",
                  "មិនទាន់មានរូបភាពសប្បុរសធម៌"
                )}
              </h3>

              <button
                type="button"
                onClick={openCreateImage}
                className="mt-5 inline-flex h-10 items-center gap-2 rounded-lg bg-red-600 px-5 text-[11px] font-bold text-white hover:bg-red-700"
              >
                <FiPlus size={14} />
                {tr(
                  "charity.addImage",
                  "Add Image",
                  "បន្ថែមរូបភាព"
                )}
              </button>
            </div>
          ) : (
            <>
              <div className="hidden overflow-x-auto lg:block">
                <table className="w-full min-w-[900px] border-collapse">
                  <thead>
                    <tr className="bg-slate-50 text-left">
                      {[
                        tr("common.image", "Image", "រូបភាព"),
                        tr("common.title", "Title", "ចំណងជើង"),
                        tr(
                          "common.description",
                          "Description",
                          "ការពិពណ៌នា"
                        ),
                        tr("common.order", "Order", "លំដាប់"),
                        tr("common.status", "Status", "ស្ថានភាព"),
                        tr("common.actions", "Actions", "សកម្មភាព"),
                      ].map((heading) => (
                        <th
                          key={heading}
                          className="border-b border-slate-200 px-4 py-3 text-[10px] font-bold uppercase tracking-[0.1em] text-slate-500"
                        >
                          {heading}
                        </th>
                      ))}
                    </tr>
                  </thead>

                  <tbody>
                    {filteredImages.map((item) => (
                      <tr
                        key={item.id}
                        className="border-b border-slate-100 last:border-b-0 hover:bg-slate-50/70"
                      >
                        <td className="px-4 py-4">
                          <div className="h-16 w-24 overflow-hidden rounded-lg bg-slate-100">
                            <img
                              src={getImageUrl(item.image)}
                              alt={localized(item, "title", "Charity")}
                              className="h-full w-full object-cover"
                            />
                          </div>
                        </td>

                        <td className="px-4 py-4">
                          <p className="max-w-[220px] truncate text-[13px] font-bold text-blue-950">
                            {localized(item, "title", "—")}
                          </p>
                        </td>

                        <td className="px-4 py-4">
                          <p className="max-w-[320px] line-clamp-2 text-[11px] leading-5 text-slate-500">
                            {localized(item, "description", "—")}
                          </p>
                        </td>

                        <td className="px-4 py-4 text-[12px] font-semibold text-slate-700">
                          {item.order ?? 0}
                        </td>

                        <td className="px-4 py-4">
                          <button
                            type="button"
                            onClick={() => toggleImageStatus(item)}
                            className={`inline-flex h-8 items-center rounded-full px-3 text-[10px] font-bold ${
                              item.is_active
                                ? "bg-emerald-100 text-emerald-700"
                                : "bg-red-100 text-red-700"
                            }`}
                          >
                            {item.is_active
                              ? tr("common.active", "Active", "សកម្ម")
                              : tr(
                                  "common.inactive",
                                  "Inactive",
                                  "អសកម្ម"
                                )}
                          </button>
                        </td>

                        <td className="px-4 py-4">
                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={() => openEditImage(item)}
                              className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 text-blue-900 hover:border-blue-900 hover:bg-blue-50"
                            >
                              <FiEdit2 size={14} />
                            </button>

                            <button
                              type="button"
                              onClick={() => deleteImage(item)}
                              disabled={deletingId === item.id}
                              className="flex h-9 w-9 items-center justify-center rounded-lg border border-red-200 bg-red-50 text-red-600 hover:bg-red-600 hover:text-white disabled:opacity-60"
                            >
                              {deletingId === item.id ? (
                                <span className="h-4 w-4 animate-spin rounded-full border-2 border-red-300 border-t-red-600" />
                              ) : (
                                <FiTrash2 size={14} />
                              )}
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="grid grid-cols-1 gap-4 p-4 sm:grid-cols-2 lg:hidden">
                {filteredImages.map((item) => (
                  <article
                    key={item.id}
                    className="overflow-hidden rounded-2xl border border-slate-200 bg-white"
                  >
                    <div className="h-[210px] bg-slate-100">
                      <img
                        src={getImageUrl(item.image)}
                        alt={localized(item, "title", "Charity")}
                        className="h-full w-full object-cover"
                      />
                    </div>

                    <div className="p-4">
                      <h3 className="text-[15px] font-bold text-blue-950">
                        {localized(item, "title", "—")}
                      </h3>

                      <p className="mt-2 line-clamp-3 text-[11px] leading-5 text-slate-500">
                        {localized(item, "description", "—")}
                      </p>

                      <div className="mt-4 flex items-center justify-between border-t border-slate-200 pt-4">
                        <button
                          type="button"
                          onClick={() => toggleImageStatus(item)}
                          className={`rounded-full px-3 py-1 text-[10px] font-bold ${
                            item.is_active
                              ? "bg-emerald-100 text-emerald-700"
                              : "bg-red-100 text-red-700"
                          }`}
                        >
                          {item.is_active
                            ? tr("common.active", "Active", "សកម្ម")
                            : tr(
                                "common.inactive",
                                "Inactive",
                                "អសកម្ម"
                              )}
                        </button>

                        <div className="flex gap-2">
                          <button
                            type="button"
                            onClick={() => openEditImage(item)}
                            className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 text-blue-900"
                          >
                            <FiEdit2 size={14} />
                          </button>

                          <button
                            type="button"
                            onClick={() => deleteImage(item)}
                            disabled={deletingId === item.id}
                            className="flex h-9 w-9 items-center justify-center rounded-lg border border-red-200 bg-red-50 text-red-600 disabled:opacity-60"
                          >
                            <FiTrash2 size={14} />
                          </button>
                        </div>
                      </div>
                    </div>
                  </article>
                ))}
              </div>
            </>
          )}
        </section>
      </div>
    </main>
  );
};

export default AdminCharity;
